package com.jaydeep.jobhunter;
import jakarta.mail.*;import jakarta.mail.internet.*;import java.util.*;
public class EmailSender {public void send(List<Job> jobs)throws MessagingException{String user=req("GMAIL_USER"),pass=req("GMAIL_APP_PASSWORD"),to=req("MAIL_TO");Properties p=new Properties();p.put("mail.smtp.host","smtp.gmail.com");p.put("mail.smtp.port","587");p.put("mail.smtp.auth","true");p.put("mail.smtp.starttls.enable","true");Session s=Session.getInstance(p,new Authenticator(){protected PasswordAuthentication getPasswordAuthentication(){return new PasswordAuthentication(user,pass);}});MimeMessage m=new MimeMessage(s);m.setFrom(new InternetAddress(user));m.setRecipients(Message.RecipientType.TO,InternetAddress.parse(to));m.setSubject("JobHunter: "+jobs.size()+" new matching opportunities");StringBuilder h=new StringBuilder("<h2>🔥 New job opportunities for 2027</h2><p>Found "+jobs.size()+" new roles matching your profile.</p>");int n=1;for(Job j:jobs){h.append("<hr><h3>").append(n++).append(". ").append(e(j.title())).append(" — ").append(e(j.company())).append("</h3><p><b>Match:</b> ").append(JobMatcher.score(j)).append("% &nbsp; <b>Location:</b> ").append(e(j.location())).append("</p><p><a href=\"").append(e(j.url())).append("\">👉 APPLY / VIEW JOB</a></p>");}m.setContent(h.toString(),"text/html; charset=UTF-8");Transport.send(m);}private static String req(String k){String v=System.getenv(k);if(v==null||v.isBlank())throw new IllegalStateException("Missing "+k);return v;}private static String e(String s){return s==null?"":s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;");}}
